import{_ as i,V as e,W as a,Z as d}from"./framework-828e3e61.js";const l={},t=d('<h1 id="《实现领域驱动设计》-一-ddd入门" tabindex="-1"><a class="header-anchor" href="#《实现领域驱动设计》-一-ddd入门" aria-hidden="true">#</a> 《实现领域驱动设计》（一）DDD入门</h1><blockquote><p>DDD不应该是一个仪式性的过程，更不应该成为你项目进度的阻碍。</p><p>你可以采用敏捷开发方法，或者寻找另外的方法来帮你更深层次地了解自己的业务领域。</p><p>我们的目标应该是创造一个可测试的、可伸缩的、组织良好的软件模型。 DDD 同时提供了战略上的和战 术 (Tactical ) 上的建模工具来帮助我们设计高质量的软件模型。</p></blockquote><h2 id="什么是领域模型" tabindex="-1"><a class="header-anchor" href="#什么是领域模型" aria-hidden="true">#</a> 什么是领域模型？</h2><p>领域模型是关于某个特定业务领域的软件模型。通常，领域模型通过对象模型来实现，这些对象同时包含了数据和行为，并且表达了准确的业务含义。</p><h2 id="为什么需要ddd" tabindex="-1"><a class="header-anchor" href="#为什么需要ddd" aria-hidden="true">#</a> 为什么需要DDD</h2><ul><li>领域专家和开发者一起工作，开发出来的软件可以准确的传达业务规则。此时软件就行领域专家编码出来的。。。</li><li>可以帮助业务人员自我提高，在ddd中每个人都在学习以及贡献知识。</li><li>集中知识，确保软件知识不只掌握在少数人手中。比如开发离职。。。</li><li>通用语言。不需要在业务人员(领域专家)、开发者、软件之间进行翻译。</li><li>设计就是代码，代码就是设计。</li><li>战略设计告诉我们理解哪些投入是重要的，哪些资产是可以重新使用的。战术设计帮我们理解ddd中各个组件。</li></ul><h2 id="贫血症和失忆症" tabindex="-1"><a class="header-anchor" href="#贫血症和失忆症" aria-hidden="true">#</a> 贫血症和失忆症</h2><blockquote><p>你的领域对象中是不是主要是些公有的gelter和setter方法，并且几乎没有业务逻辑，或者甚至完全没有业务逻辑对象嘛，主要就是用来容纳属性值的。</p><p>软件组件经常使用的领域对象是否包含了系统主要的业务逻辑，并且多数情况 下你需要调用那些getter 和 setter ? 你可能会将这样的 客 户代码称为服务层或者应 用 层代 码 。</p></blockquote><p>贫血领域对象代码中通常不代表具体的业务含义，即业务意图不明确。方法本身增加了潜在的复杂性。对象本身知识一个数据持有器。</p><p>随着时间的推移以及业务的不断迭代，原有方法变的没人可以清楚他本来的含义，我们将这种现象称为由贫血症引发的失忆症。</p><h2 id="通用语言" tabindex="-1"><a class="header-anchor" href="#通用语言" aria-hidden="true">#</a> 通用语言</h2><figure><img src="https://cdn.jsdelivr.net/gh/fxzbiz/img@url/2024/06/22/4TkSMH.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><figure><img src="https://cdn.jsdelivr.net/gh/fxzbiz/img@url/2024/06/22/MgPaRA.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h2 id="ddd的业务价值" tabindex="-1"><a class="header-anchor" href="#ddd的业务价值" aria-hidden="true">#</a> DDD的业务价值</h2><ul><li>获得了有价值的领域模型。将关注点放在业务上。</li><li>业务有了更准确的定义和理解。</li><li>领域专家可以为软件设计作出贡献。</li><li>更好的用户体验。软件本身能对用户起到培训作用。</li><li>更清晰的模型架构，更好的企业架构。</li></ul><h2 id="挑战" tabindex="-1"><a class="header-anchor" href="#挑战" aria-hidden="true">#</a> 挑战</h2><ul><li>为创建通用语言腾出更多的精力。</li><li>需要持续引入领域专家。</li><li>改变开发者对领域的思考方式。</li></ul>',17),r=[t];function n(h,c){return e(),a("div",null,r)}const s=i(l,[["render",n],["__file","ddd-introduction.html.vue"]]);export{s as default};
